package com.notificationservice.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="telegram_preferences") public class TelegramPreferenceEntity {
 @Id @Column(name="user_id") private UUID userId; @Column(name="new_users",nullable=false) private boolean newUsers=true; @Column(nullable=false) private boolean actionable=true; @Column(name="system_events",nullable=false) private boolean systemEvents=true; @Column(name="login_events",nullable=false) private boolean loginEvents=false; @Column(name="question_pending",nullable=false) private boolean questionPending=true; @Column(name="question_resubmitted",nullable=false) private boolean questionResubmitted=true; @Column(name="subject_events",nullable=false) private boolean subjectEvents=true; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 public UUID getUserId(){return userId;} public void setUserId(UUID v){userId=v;} public boolean isNewUsers(){return newUsers;} public void setNewUsers(boolean v){newUsers=v;} public boolean isActionable(){return actionable;} public void setActionable(boolean v){actionable=v;} public boolean isSystemEvents(){return systemEvents;} public void setSystemEvents(boolean v){systemEvents=v;} public boolean isLoginEvents(){return loginEvents;} public void setLoginEvents(boolean v){loginEvents=v;} public boolean isQuestionPending(){return questionPending;} public void setQuestionPending(boolean v){questionPending=v;} public boolean isQuestionResubmitted(){return questionResubmitted;} public void setQuestionResubmitted(boolean v){questionResubmitted=v;} public boolean isSubjectEvents(){return subjectEvents;} public void setSubjectEvents(boolean v){subjectEvents=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;}
}
